const panel=document.querySelector('#panel'),hint=document.querySelector('#hint'),toast=document.querySelector('#toast');let score=18,stage=0,panelOpen=false,toastTimer;
const setScore=n=>{score=Math.min(100,Math.max(0,n));document.querySelector('#score-label').textContent=score+'%';document.querySelector('#score-bar').style.width=score+'%'};
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2100)}
function openPanel(){panelOpen=true;panel.classList.add('open');hint.style.opacity=0;renderDialogue()}
function closePanel(){panelOpen=false;panel.classList.remove('open');}
function renderDialogue(){const label=document.querySelector('#scene-label'),title=document.querySelector('#dialogue-title'),text=document.querySelector('#dialogue-text'),choices=document.querySelector('#choices');choices.innerHTML='';
let options;
if(stage===0){label.textContent='Una primera impresión';title.textContent='¿Qué le dices?';text.textContent='Alex se vuelve hacia ti con una sonrisa tranquila. La noche apenas comienza.';options=[['Romper el hielo con una pregunta','¿Qué canción te gustaría que sonara ahora?',12],['Hacer un cumplido sincero','Me encanta la calma que transmites.',14],['Preguntar si le apetece charlar','¿Te gustaría que nos conociéramos un poco?',18]];}
else if(stage===1){label.textContent='La conversación fluye';title.textContent='Alex parece a gusto';text.textContent='La charla se vuelve fácil. Una brisa tibia mueve las luces sobre vosotros.';options=[['Contar algo divertido de ti','Compartir también es escuchar.',12],['Preguntar qué le hace feliz','Alex sonríe al hablar de sus pequeñas cosas favoritas.',14],['Proponer un baile','Solo si te apetece; podemos seguir charlando también.',16]];}
else if(stage===2){label.textContent='Una invitación';title.textContent='¿Compartimos este momento?';text.textContent='Alex te mira a los ojos. Hay una chispa, pero no hay prisa: el ritmo lo decidís entre los dos.';options=[['Invitarle a bailar','Un sí entusiasta, o seguimos disfrutando del jardín.',20],['Quedarse conversando','La compañía también es suficiente.',12],['Preguntar qué le apetece','La noche es vuestra; sus deseos importan tanto como los tuyos.',16]];}
else{label.textContent='Con confianza y cuidado';title.textContent='¿Qué os gustaría ahora?';text.textContent='Después del baile, Alex te sonríe y te toma la mano con suavidad. Puedes preguntar, escuchar o dejarlo aquí: cualquier respuesta está bien.';options=[['Preguntar si quiere un momento a solas','Una invitación, nunca una expectativa.',13,'intimate'],['Dar las gracias y seguir bailando','Disfrutar de la noche sin más.',6,'dance'],['Despedirse con cariño','Un buen encuentro no necesita promesas.',0,'end']];}
options.forEach(([labelTxt,detail,points,action])=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${labelTxt}<small>${detail}</small>`;b.onclick=()=>choose(points,action);choices.appendChild(b)});}
function choose(points,action){if(action==='intimate'){document.querySelector('#ending').classList.add('show');closePanel();return}if(action==='end'){closePanel();showToast('Gracias por una noche bonita ✦');stage=0;setScore(18);return}setScore(score+points);if(action==='dance'){danceUntil=performance.now()+8000;stage=Math.min(stage+1,3);closePanel();showToast('Un baile compartido, sin prisa ✦');return}if(stage===0&&score>=38)stage=1;else if(stage===1&&score>=62)stage=2;else if(stage>=2)stage=3;closePanel();showToast(stage===1?'Alex se siente en confianza contigo.':'La conexión crece, paso a paso.');}
document.querySelector('#close').onclick=closePanel;document.querySelector('#mobile-action').onclick=()=>interact();document.querySelector('#restart').onclick=()=>{document.querySelector('#ending').classList.remove('show');score=18;stage=0;setScore(score);player.position.set(-2.2,0,2.7);closePanel()};
function interact(){if(panelOpen){closePanel();return}if(player.position.distanceTo(alex.position)<2.55)openPanel();else showToast('Acércate un poco más a Alex');}
const keys={};window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'||k==='enter')interact()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('.pad').forEach(button=>{const key=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;button.setPointerCapture(e.pointerId)});button.addEventListener('pointerup',()=>keys[key]=false);button.addEventListener('pointercancel',()=>keys[key]=false)});
let soundOn=false;document.querySelector('#sound').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';showToast(soundOn?'La banda sonora ambiental está activada':'Sonido desactivado');};
let danceUntil=0,last=performance.now(),camTarget=new THREE.Vector3();const clock=new THREE.Clock();function animate(now){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);let dx=0,dz=0;if(!panelOpen){if(keys.a||keys.arrowleft)dx-=1;if(keys.d||keys.arrowright)dx+=1;if(keys.w||keys.arrowup)dz-=1;if(keys.s||keys.arrowdown)dz+=1}if(dx||dz){const len=Math.hypot(dx,dz);player.position.x+=dx/len*dt*3.1;player.position.z+=dz/len*dt*3.1;player.position.x=THREE.MathUtils.clamp(player.position.x,-6,6);player.position.z=THREE.MathUtils.clamp(player.position.z,-7,7);player.rotation.y=Math.atan2(dx,dz);}
const near=player.position.distanceTo(alex.position)<2.55;if(near&&!panelOpen){hint.innerHTML='<span class="key">E</span> para hablar con Alex';hint.style.opacity=1}else if(!panelOpen){hint.innerHTML='<span class="key">W</span><span class="key">A</span><span class="key">S</span><span class="key">D</span> para moverte <span style="color:#ffffff66;margin:0 8px">·</span><span class="key">E</span> para hablar';hint.style.opacity=1}
const targetAngle=Math.atan2(player.position.x-alex.position.x,player.position.z-alex.position.z);alex.rotation.y=THREE.MathUtils.damp(alex.rotation.y,targetAngle,1.8,dt);if(now<danceUntil){player.rotation.y=Math.sin(now*.004)*.4;alex.rotation.y=Math.PI+Math.sin(now*.004+.6)*.4;player.position.x+=Math.sin(now*.004)*dt*.12;alex.position.x=.5+Math.cos(now*.004)*.12;}
camTarget.set(player.position.x*.48,player.position.y+4.4,player.position.z+7.3);camera.position.lerp(camTarget,1-Math.exp(-dt*2.7));camera.lookAt(player.position.x*.25,1.15,player.position.z-1.6);warm.intensity=17+Math.sin(now*.0018)*1.5;renderer.render(scene,camera)}requestAnimationFrame(animate);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2))});

