function resetEndingScene(){const overlay=document.querySelector('#ending');endingStep=0;overlay.dataset.scene='kiss';overlay.classList.remove('transitioning');document.querySelector('#ending-eyebrow').textContent='Escena 1 · Bajo las luces';document.querySelector('#ending-title').textContent='Un beso compartido';document.querySelector('#ending-text').textContent='Alex se acerca despacio y se detiene un instante, dándote espacio para elegir. Tú respondes acercándote también. El beso es tierno y mutuo; las luces del jardín se vuelven borrosas alrededor.';document.querySelector('#ending-note').textContent='Un momento íntimo solo sucede cuando ambos lo desean.';document.querySelector('#scene-continue').textContent='Ir a un lugar tranquilo'}
let endingStep=0;function advanceEnding(){const overlay=document.querySelector('#ending');if(endingStep===0){endingStep=1;overlay.classList.add('transitioning');setTimeout(()=>{overlay.dataset.scene='private';document.querySelector('#ending-eyebrow').textContent='Escena 2 · A solas';document.querySelector('#ending-title').textContent='Con confianza y cuidado';document.querySelector('#ending-text').textContent='En un lugar tranquilo, os tomáis un momento para hablar y confirmar que ambos queréis continuar. Alex te pregunta cómo te sientes; compartís otro sí. La puerta se cierra y la cámara se queda fuera.';document.querySelector('#ending-note').textContent='Podéis parar o cambiar de idea en cualquier momento.';document.querySelector('#scene-continue').textContent='Fundido a negro';overlay.classList.remove('transitioning')},450);return}if(endingStep===1){endingStep=2;overlay.classList.add('transitioning');overlay.dataset.scene='fade';setTimeout(()=>{overlay.dataset.scene='dawn';document.querySelector('#ending-eyebrow').textContent='Escena 3 · A la mañana siguiente';document.querySelector('#ending-title').textContent='Una sonrisa cómplice';document.querySelector('#ending-text').textContent='La noche pasa en privado. Al amanecer, compartís una taza de café y os preguntáis cómo estáis. Lo que ocurrió queda fuera de plano, como un recuerdo íntimo que solo os pertenece a vosotros.';document.querySelector('#ending-note').textContent='Gracias por jugar una historia donde el cuidado y el consentimiento importan.';document.querySelector('#scene-continue').textContent='Volver al jardín';overlay.classList.remove('transitioning')},1250);return}document.querySelector('#restart').click()}
document.querySelector('#scene-continue').onclick=advanceEnding;document.querySelector('#close').onclick=closePanel;document.querySelector('#mobile-action').onclick=()=>interact();document.querySelector('#restart').onclick=()=>{document.querySelector('#ending').classList.remove('show');resetEndingScene();score=18;stage=0;setScore(score);player.position.set(-1.35,0,2.7);closePanel()};

